package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;

/** Two-stage polynomial score equations with an actual, fully refitted PLS or GSCA first stage. */
public final class ComponentPolynomial {
    private ComponentPolynomial(){}
    public record Fit(ComponentScores.Fit firstStage,NonlinearPls.ScoreFit polynomial,List<String> warnings){public Fit{warnings=List.copyOf(warnings);if(!firstStage.model().names().equals(polynomial.names()))throw new IllegalArgumentException("Component and polynomial identities differ.");}}
    public record Resampled(Fit point,Bootstrap.Result inference){}
    public static Fit fit(double[][] data,ComponentScores.Model model,NonlinearPls.Specification specification){var first=ComponentScores.fit(data,model);return describe(first,first.scores(),specification,true);}
    private static Fit describe(ComponentScores.Fit first,double[][] aligned,NonlinearPls.Specification specification,boolean details){var polynomial=NonlinearPls.fitScores(aligned,first.model().names(),first.model().paths(),specification,true,details);List<String> warnings=new ArrayList<>(first.warnings());warnings.addAll(polynomial.warnings());warnings.add("The component estimator fits the main-effects model first. Hierarchical polynomial regressions of its unit-variance scores are a second stage, not a joint nonlinear GSCA objective or latent nonlinear maximum likelihood.");warnings.add("Generated-score standard errors require complete procedure resampling. Every bootstrap or jackknife re-estimates component weights and re-aligns score signs before polynomial fitting.");return new Fit(first,polynomial,warnings);}
    public static Resampled bootstrap(double[][] data,ComponentScores.Model model,NonlinearPls.Specification specification,Bootstrap.Options options,IntConsumer progress){var point=fit(data,model,specification);double[][] reference=point.firstStage().scores();var parameters=NonlinearPls.scoreParameters(point.polynomial(),false);if(parameters.size()>50000)throw new IllegalArgumentException("More than 50,000 polynomial inference targets.");var result=Resampling.run(data,parameters,NonlinearPls.scoreValues(point.polynomial(),false),options,(sample,rows)->{var first=ComponentScores.fit(sample,model);var aligned=ComponentScores.align(first.scores(),reference,rows);return NonlinearPls.scoreValues(NonlinearPls.fitScores(aligned,model.names(),model.paths(),specification,true,false),false);},progress,"Full-pipeline "+model.estimator()+" polynomial score model","All component weights and scores are refitted, normalized and aligned against original sampled row indices; every polynomial coefficient and local derivative is then refitted. IID case bootstrap; intervals are pointwise and unadjusted across targets.");List<String> warnings=new ArrayList<>(result.warnings());warnings.addAll(point.warnings());var inference=new Bootstrap.Result(result.options(),result.method(),result.randomGenerator(),result.signHandling(),result.successful(),result.failed(),result.failures(),result.estimates(),warnings,result.estimator());return new Resampled(point,inference);}
}
